chapters.example:
{
  "permissions": {
    "defaultMode": "default"
  }
}

{
  "hooks": {
    "SessionStart": [{"hooks": [{"type": "command", "command": "echo 'Session started' >> ~/.claude/session.log"}]}],
    "UserPromptSubmit": [{"hooks": [{"type": "command", "command": "bash ~/.claude/hooks/check-prompt-secrets.sh"}]}],
    "PreCompact": [{"hooks": [{"type": "command", "command": "bash ~/.claude/hooks/save-state.sh"}]}]
  }
}

{
  "mcpServers": {
    "playwright": {
      "command": "npx",
      "args": ["@playwright/mcp@latest"],
      "env": {}
    }
  }
}

{
  "mcpServers": {
    "playwright": {
      "command": "npx",
      "args": ["@playwright/mcp@latest"],
      "env": {}
    },
    "slack": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-slack"],
      "env": {
        "SLACK_BOT_TOKEN": "${SLACK_BOT_TOKEN:-default-dev-token}",
        "SLACK_TEAM_ID": "${SLACK_TEAM_ID}"
      }
    },
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres"],
      "env": {
        "POSTGRES_CONNECTION_STRING": "${PG_URL:-postgresql://user:pass@localhost/mydb}"
      }
    }
  }
}

{
  "sandbox": {
    "network": {
      "deniedDomains": ["legacy-scada.corp.internal"]
    }
  },
  "autoMode": {
    "hard_deny": [
      "$defaults",
      "Never touch the production database tooling, no matter how safe the action looks"
    ]
  },
  "disableSkillShellExecution": true
}

claude -p "Categorize this issue" \
  --output-format json \
  --json-schema '{
    "type":"object",
    "properties":{
      "category":{"type":"string","enum":["bug","feature","docs"]},
      "severity":{"type":"integer","minimum":1,"maximum":5}
    }
  }'
